pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }
    function testRegression_property() public {
        address token = address(new SimpleToken());
        address from = address(0x1234);
        SimpleToken(token).mint(from, 100);
        vm.prank(from);
        SimpleToken(token).approve(address(c), 100);

        address[] memory tos = new address[](1);
        tos[0] = address(0x5678);

        vm.prank(from);
        bool ret = c.transfer(from, token, tos, 10);
        assertTrue(ret);
    }
}

contract SimpleToken {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        require(allowance[from][msg.sender] >= value);
        require(balanceOf[from] >= value);
        allowance[from][msg.sender] -= value;
        balanceOf[from] -= value;
        balanceOf[to] += value;
        return true;
    }
}
